## Consolidated “Secure‑by‑Default” Boilerplate

Below is a **complete, production‑ready** `app.js` that incorporates all the recommendations above while keeping the original functionality intact.

```js
// app.js – Hardened version
'use strict';

require('dotenv').config();               // Load .env (e.g., JWT_SECRET, PORT)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
// const { body, validationResult } = require('express-validator'); // Uncomment when you add POST/PUT routes

const app = express();

/* -------------------------------------------------------------
   1️⃣ Core security middlewares
   ------------------------------------------------------------- */
app.use(helmet());                         // Sets X‑Frame-Options, CSP, HSTS, etc.
app.use(express.json());                   // Parse JSON bodies
app.use(express.urlencoded({ extended: false }));

// CORS – tighten in production
app.use(
  cors({
    origin:
      process.env.NODE_ENV === 'production'
        ? ['https://myapp.example.com']
        : '*',
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// Rate limiting (global)
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 min
    max: 100,                // max 100 requests per IP per window
    message: { error: 'Too many requests – try later.' },
  })
);

// Request logging (combined Apache style)
app.use(morgan('combined'));

/* -------------------------------------------------------------
   2️⃣ Helper: authentication middleware (JWT)
   ------------------------------------------------------------- */
const auth = (requiredRoles = []) => (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing token' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    // role‑based check (optional)
    if (requiredRoles.length && !requiredRoles.includes(payload.role))
      return res.status(403).json({ error: 'Insufficient privileges' });

    req.user = payload; // attach user info for downstream handlers
    next();
  } catch (e) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

/* -------------------------------------------------------------
   3️⃣ Routes
   ------------------------------------------------------------- */

// Health – public but do not expose too much internal info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/* Example static data – in a real app replace with DB calls */
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

/**
 * GET /users – protected route.
 * Only authenticated callers can see the list.
 * We filter out e‑mail unless the caller has a privileged role.
 */
app.get('/users', auth(['admin', 'support']), (req, res) => {
  const safe = USERS.map(u => ({
    id: u.id,
    name: u.name,
    // Only expose email to admins
    ...(req.user.role === 'admin' && { email: u.email })
  }));
  res.json(safe);
});

/* -------------------------------------------------------------
   4️⃣ Global error handler (doesn't leak stack traces)
   ------------------------------------------------------------- */
app.use((err, _req, res, _next) => {
  console.error(err); // log full error for ops
  res.status(500).json({ error: 'Internal Server Error' });
});

/* -------------------------------------------------------------
   5️⃣ Server start – only when file is executed directly
   ------------------------------------------------------------- */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  // Trust proxy when behind a load‑balancer (required for HTTPS redirect logic)
  app.enable('trust proxy');

  // Optional: force HTTPS in production
  if (process.env.NODE_ENV === 'production') {
    app.use((req, res, next) => {
      if (req.secure) return next();
      res.redirect(`https://${req.headers.host}${req.url}`);
    });
  }

  app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
}

module.exports = app; // Export for unit‑testing
```

