const allowedOrigins = [process.env.FRONTEND_ORIGIN || 'https://myapp.example.com'];
app.use(cors({
  origin: (origin, cb) => {
    if (!origin) return cb(null, true); // allow non‑browser tools
    if (allowedOrigins.includes(origin)) return cb(null, true);
    cb(new Error('Not allowed by CORS'));
  },
  credentials: true,
}));

// 3. Logging
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// 4. Rate limiting (global + per‑route)
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 200,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(globalLimiter);

// ------------------------------------------------------------
// 5. HTTPS enforcement (optional, safe behind a reverse proxy)
// ------------------------------------------------------------
app.use((req, res, next) => {
  if (req.secure || req.headers['x-forwarded-proto'] === 'https') {
    return next();
  }
  res.redirect(`https://${req.headers.host}${req.url}`);
});

// ------------------------------------------------------------
// 6. Routes
// ------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', verifyToken, (req, res) => {
  const isAdmin = req.user.role === 'admin';
  const users = [
    { id: 1, name: 'Alice', email: isAdmin ? 'alice@example.com' : undefined },
    { id: 2, name: 'Bob',   email: isAdmin ? 'bob@example.com'   : undefined },
  ];
  res.json(users);
});

// ------------------------------------------------------------
// 7. Central error handler (must be after all routes)
// ------------------------------------------------------------
app.use((err, req, res, next) => { // eslint-disable-line no-unused-vars
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message,
  });
});

// ------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

