### 2️⃣ Use a **Secrets Manager** in Production

Below are three common ways to retrieve secrets at startup. Pick the one that matches your cloud provider.

#### a) AWS Secrets Manager (Node.js)

```bash
npm i aws-sdk   # v3: @aws-sdk/client-secrets-manager
```

```js
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Retrieves a secret from AWS Secrets Manager.
 * @param {string} secretName - Name or ARN of the secret.
 * @returns {Promise<string|object>} - Plain string or parsed JSON.
 */
async function getSecret(secretName) {
  const cmd = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(cmd);
  const secretString = response.SecretString;
  try {
    return JSON.parse(secretString);   // if you stored a JSON object
  } catch {
    return secretString;               // plain string (e.g., JWT secret)
  }
}

// Example usage at app start‑up
(async () => {
  const dbCreds = await getSecret('prod/dbCredentials'); // expects {"username":"…","password":"…"}
  process.env.DATABASE_URL = `postgres://${dbCreds.username}:${encodeURIComponent(dbCreds.password)}@db.internal:5432/production`;

  const jwtSecret = await getSecret('prod/jwtSecret');
  process.env.JWT_SECRET = jwtSecret;
})();
```

*Key Points*  
* The code runs **before** the server starts listening, guaranteeing that required env vars are populated.  
* The IAM role attached to the compute instance/container must have `secretsmanager:GetSecretValue` on the listed secrets.

#### b) Google Cloud Secret Manager

```bash
npm i @google-cloud/secret-manager
```

```js
// gcpSecrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function getSecret(name) {
  const [version] = await client.accessSecretVersion({ name });
  const payload = version.payload.data.toString('utf8');
  try {
    return JSON.parse(payload);
  } catch {
    return payload;
  }
}

// Example – load at startup
(async () => {
  const db = await getSecret('projects/my-project/secrets/dbCredentials/versions/latest');
  process.env.DATABASE_URL = `postgres://${db.username}:${encodeURIComponent(db.password)}@db.internal:5432/production`;

  const jwt = await getSecret('projects/my-project/secrets/jwtSecret/versions/latest');
  process.env.JWT_SECRET = jwt;
})();
```

#### c) HashiCorp Vault (generic HTTP API)

```bash
npm i node-vault
```

```js
// vaultSecrets.js
const vault = require('node-vault')({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR || 'https://vault.mycompany.com',
  token: process.env.VAULT_TOKEN, // Ideally injected via the orchestrator, not stored in code
});

async function loadSecrets() {
  const db = await vault.read('secret/data/prod/dbCredentials');
  const jwt = await vault.read('secret/data/prod/jwtSecret');

  process.env.DATABASE_URL = `postgres://${db.data.data.username}:${encodeURIComponent(db.data.data.password)}@db.internal:5432/production`;
  process.env.JWT_SECRET = jwt.data.data.value;
}
module.exports = { loadSecrets };
```

*Note:* The vault token itself should be **injected by the orchestrator** (e.g., Kubernetes ServiceAccount + Vault Agent) rather than placed in a file.

