require('dotenv').config();                // ← Load .env (e.g., JWT secret, port)
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { body, param, validationResult } = require('express-validator');

const app = express();

// --------------------  Middleware ---------------------------------
app.use(helmet());                         // Security headers (A6)
app.use(express.json());                  // Parse JSON bodies safely
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' })); // Restrict origins (A5)
app.use(morgan('combined'));              // Structured request logging (A10)

// Rate limiting: 100 requests per 15‑minute window per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// --------------------  Auth Helpers --------------------------------
