const JWT_EXPIRES_IN = '1h';

// Simple middleware to protect routes
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) return res.sendStatus(401); // No token → Unauthorized

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid token → Forbidden
    req.user = user;
    next();
  });
}

// --------------------  Sample Users (to be replaced by DB) ----------
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
  { id: 2, name: 'Bob',   email: 'bob@example.com',   role: 'user' },
];

// --------------------  Routes --------------------------------------

// Health check – keep it public but rate‑limited
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// --------------------  Authentication -----------------------------
/**
 * POST /login
 * Body: { email: string, password: string }
 * Returns a signed JWT.
 * In a real app passwords are stored hashed (bcrypt) in a DB.
 */
app.post(
  '/login',
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 })
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty())
      return res.status(400).json({ errors: errors.array() });

    const { email, password } = req.body;
    // -----------------------------------------------------------------
    // TODO: Replace the following dummy check with a DB lookup + bcrypt.
    // -----------------------------------------------------------------
    const user = USERS.find(u => u.email === email);
    if (!user || password !== 'Password123!') {
