      JWT_SECRET,
      { expiresIn: JWT_EXPIRES_IN }
    );
    res.json({ token });
  }
);

// --------------------  Protected Resources -------------------------
/**
 * GET /users
 * Returns the list of users, but **only for authenticated callers**.
 * Sensitive fields (e.g., email) can be filtered based on role.
 */
app.get('/users', authenticateToken, (req, res) => {
