## Recommendations & Code Samples

Below are **concrete steps** to move from a plain‑text `.env` file to a proper secrets‑management workflow while still keeping the convenience of `dotenv` for local development.

### 1. Keep the `.env` **only for local dev** – never ship it to production

Add it to `.gitignore` (it already is, but double‑check) and ensure your CI/CD pipeline never copies it to a production image.

```gitignore
# .gitignore
.env*
```

### 2. Load secrets **lazily** from a dedicated secrets manager

Below are three popular options. Pick the one that matches your cloud provider or preferred vault.

#### a. AWS Secrets Manager (Node SDK v3)

```js
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Retrieves a secret (JSON string) from AWS Secrets Manager.
 * Caches it in memory for the life of the process (optional).
 */
let cached = {};

async function getSecret(name) {
  if (cached[name]) return cached[name];

  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);
  const secretString = response.SecretString;

  try {
    const parsed = JSON.parse(secretString);
    cached[name] = parsed;
    return parsed;
  } catch (_) {
    // If secret is a plain string (e.g., API key)
    cached[name] = secretString;
    return secretString;
  }
}

module.exports = { getSecret };
```

**Usage in `app.js` (or any route):**

```js
const { getSecret } = require('./secrets');

app.get('/stripe-key', authenticateToken, async (req, res) => {
  try {
    const { STRIPE_SECRET_KEY } = await getSecret('myapp/stripe');
    res.json({ key: STRIPE_SECRET_KEY });   // only send if business‑logic requires it
  } catch (e) {
    console.error('Failed to fetch Stripe secret', e);
    res.sendStatus(500);
  }
});
```

*Benefit:* The secret is fetched **only when needed**, stays encrypted in transit, and can be rotated without a new deploy.

#### b. Google Cloud Secret Manager

```js
// secrets-gcp.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function getSecret(secretName) {
  const [version] = await client.accessSecretVersion({
    name: `projects/${process.env.GCP_PROJECT}/secrets/${secretName}/versions/latest`,
  });
  const payload = version.payload.data.toString('utf8');
  try {
    return JSON.parse(payload);
  } catch {
    return payload; // plain string
  }
}

module.exports = { getSecret };
```

Usage is identical to the AWS example; just replace the `require` path.

#### c. HashiCorp Vault (HTTP API)

```js
// vault.js
const fetch = require('node-fetch');

const VAULT_ADDR = process.env.VAULT_ADDR || 'https://vault.mycompany.com';
const VAULT_TOKEN = process.env.VAULT_TOKEN;   // injected via container runtime, not from .env

async function getSecret(path) {
  const resp = await fetch(`${VAULT_ADDR}/v1/${path}`, {
    headers: { 'X-Vault-Token': VAULT_TOKEN },
  });
  if (!resp.ok) throw new Error(`Vault error ${resp.status}`);
  const data = await resp.json();
  return data.data; // assumes KV v2 data format
}

module.exports = { getSecret };
```

