```js
// ---------------------------------------------------------------
// app.js – hardened Express server
// ---------------------------------------------------------------

/**
 * Security hardening notes
 * ------------------------
 * 1. Helmet adds a comprehensive set of security headers.
 * 2. cors limits which origins may call the API.
 * 3. express-rate-limit throttles abusive callers.
 * 4. express.json() limits request body size.
 * 5. morgan + winston provides request & error logging.
 * 6. JWT authentication protects privileged routes.
 * 7. HTTPS is expected to be terminated upstream (NGINX/Traefik).
 *    If you want the node process to handle TLS directly, replace
 *    app.listen() with https.createServer(...).listen().
 */

require('dotenv').config();               // Loads .env (keep secrets out of source)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');       // npm i jsonwebtoken
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ---------------------------------------------------------------
// 1️⃣  Global middleware (security headers, body parsing, etc.)
// ---------------------------------------------------------------
app.use(helmet());                         // Sets X‑Content‑Type‑Options, CSP, HSTS, etc.
app.disable('x-powered-by');               // Hide tech stack

// CORS – adjust the origin list to your front‑ends
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [], // e.g. "https://myapp.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// JSON body parser with size limit (prevents DoS via huge payloads)
app.use(express.json({ limit: '10kb' }));

// Request logging (combined format goes to stdout, can be piped to a log shipper)
app.use(morgan('combined'));

// ---------------------------------------------------------------
// 2️⃣  Rate limiting (basic DoS protection)
// ---------------------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 60 * 1000,          // 1 minute
  max: 100,                     // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/api/', apiLimiter); // apply to all routes under /api

// ---------------------------------------------------------------
// 3️⃣  Simple JWT auth middleware (replace with your auth strategy)
// ---------------------------------------------------------------
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    // `JWT_SECRET` should be a strong random string stored in .env
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// ---------------------------------------------------------------
// 4️⃣  Routes
// ---------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example protected endpoint – only authenticated users can list other users.
 * In a real system you would pull the data from a DB and apply RBAC.
 */
app.get(
  '/api/users',
  authenticate,
  // OPTIONAL: additional validation (e.g., query params for pagination)
  [
    // query('page').optional().isInt({ min: 1 }).toInt(),
    // query('size').optional().isInt({ min: 1, max: 100 }).toInt(),
  ],
  (req, res) => {
    // Validate any query params first
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Dummy data – NEVER expose raw emails unless absolutely required.
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json(users);
  }
);

// ---------------------------------------------------------------
// 5️⃣  Centralized error handler (prevent stack traces leaking)
// ---------------------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err); // You could replace this with winston logger
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal server error' : err.message,
  });
});

// ---------------------------------------------------------------
// 6️⃣  Server start
// ---------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🔒 Secure server listening on ${PORT}`);
});

module.exports = app;
```

