### 2.3. Add authentication / authorization

If the user list is **confidential**, protect it with a token‑based scheme (e.g., JWT). Create a small middleware:

```js
// ==== AUTH MIDDLEWARE =======================================================
const jwt = require('jsonwebtoken');

// Pull the secret/key from environment (never hard‑code!)
const JWT_SECRET = process.env.JWT_SECRET || 'fallback-secret';

function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }

  const token = authHeader.split(' ')[1]; // Expect "Bearer <token>"
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    // Attach user info to request for downstream checks
    req.user = payload;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}
```

Protect the `/users` route:

```js
app.get('/users', authenticate, (req, res) => {
  // In a real app, you would fetch users from a DB, applying RBAC checks.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' }
  ]);
});
```

*Why?* This fixes **A02: Broken Access Control** and **A07: Identification & Authentication Failures**.

