  require('dotenv').config({ path: `.env.${process.env.NODE_ENV || 'development'}` });
} else {
  // Production – fetch from secret manager (example using AWS)
  const { loadSecrets } = require('./secrets');
  await loadSecrets();   // make sure the start‑up script awaits this
}
```

