// Secure Express application – baseline hardening
// ------------------------------------------------------------
require('dotenv').config();               //  <-- Load .env configuration
const express = require('express');
const helmet = require('helmet');         // Security headers
const cors   = require('cors');           // CORS handling
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // Request logging
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ------------------------------------------------------------
// Global middleware
// ------------------------------------------------------------
// 1) Hide Express fingerprint
app.disable('x-powered-by');

// 2) Add security‑related HTTP headers
app.use(helmet());

// 3) Enable CORS (adjust origin for production)
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  methods: ['GET','POST','PUT','DELETE'],
  credentials: true
}));

// 4) Rate limiting – basic brute‑force/DoS protection
