  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 5) JSON body parsing (if you add POST/PUT later)
app.use(express.json());

// 6) Structured request logging (avoid logging sensitive data)
app.use(morgan('combined'));

// ------------------------------------------------------------
// Health endpoint (no auth needed, but keep it minimal)
// ------------------------------------------------------------
