  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com' }
];

// Example: only authenticated users can list users
app.get('/users',
  authenticate,
  (req, res) => {
    // Remove sensitive fields before sending (e.g., email can be omitted or masked)
    const safeUsers = USERS.map(u => ({
      id: u.id,
      name: u.name,
      // email: u.email // comment out or hash/mask if not needed
    }));
    res.json(safeUsers);
  }
);

// ------------------------------------------------------------
// Global error handler (no stack traces in production)
// ------------------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err);                 // Still log the error server‑side
  const status = err.status || 500;
  const message = (process.env.NODE_ENV === 'production')
    ? 'Internal server error'
    : err.message;
  res.status(status).json({ error: message });
});

