// config/secrets.js
require('dotenv').config();      // still supports local .env for dev

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
// ──────────────────────────────────────────────────────────────────────────────
// 1️⃣ Choose the provider you need – comment out the others or make this
//    configurable via an env flag (e.g. SECRET_PROVIDER=aws|azure|vault)
// ──────────────────────────────────────────────────────────────────────────────

// --------------------------------------------------------
// AWS Secrets Manager implementation (default)
// --------------------------------------------------------
const awsClient = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Fetch a secret value from AWS Secrets Manager.
 * Caches the result in memory for the lifetime of the process.
 */
const secretCache = new Map();

async function getAwsSecret(secretName) {
  if (secretCache.has(secretName)) {
    return secretCache.get(secretName);
  }

  const cmd = new GetSecretValueCommand({ SecretId: secretName });
  const resp = await awsClient.send(cmd);
  const secretString = resp.SecretString; // Assuming a plain string (or JSON)
  secretCache.set(secretName, secretString);
  return secretString;
}

/**
 * Wrapper that decides where to read a secret from.
 *   - If SECRET_PROVIDER=aws  → AWS Secrets Manager
 *   - If SECRET_PROVIDER=env  → plain process.env (fallback)
 */
async function getSecret(key) {
  const provider = process.env.SECRET_PROVIDER || 'env';

  // -----------------------------------------------------------------
  // 1️⃣ Env fallback (including .env for local dev)
  // -----------------------------------------------------------------
  if (provider === 'env') {
    if (!process.env[key]) {
      console.warn(`[⚠️] Missing environment variable ${key}`);
    }
    return process.env[key];
  }

  // -----------------------------------------------------------------
  // 2️⃣ AWS Secrets Manager
  // -----------------------------------------------------------------
  if (provider === 'aws') {
    // In AWS you usually store each secret under a logical name,
    // e.g. "myapp/jwt-secret". You can map a logical key to that name.
    const secretName = process.env[`AWS_SECRET_${key}`] || `myapp/${key.toLowerCase()}`;
    try {
      const secretValue = await getAwsSecret(secretName);
      // If you stored a JSON document, parse it here.
      // return JSON.parse(secretValue)[key];
      return secretValue;
    } catch (err) {
      console.error(`[❌] Failed to load secret ${secretName} from AWS Secrets Manager`, err);
      throw err;
    }
  }

  // -----------------------------------------------------------------
  // 3️⃣ Azure Key Vault (placeholder – uncomment if you use Azure)
  // -----------------------------------------------------------------
  // if (provider === 'azure') {
  //   const { DefaultAzureCredential } = require('@azure/identity');
  //   const { SecretClient } = require('@azure/keyvault-secrets');
  //   const credential = new DefaultAzureCredential();
  //   const vaultUrl = process.env.AZURE_KEYVAULT_URL;
  //   const client = new SecretClient(vaultUrl, credential);
  //   const secret = await client.getSecret(key);
  //   return secret.value;
  // }

  // -----------------------------------------------------------------
  // 4️⃣ HashiCorp Vault (placeholder)
  // -----------------------------------------------------------------
  // if (provider === 'vault') {
  //   const vault = require('node-vault')({ endpoint: process.env.VAULT_ADDR, token: process.env.VAULT_TOKEN });
  //   const secret = await vault.read(`secret/data/${key}`);
  //   return secret.data.data[key];
  // }

  throw new Error(`Unsupported SECRET_PROVIDER=${provider}`);
}

module.exports = {
  /**
   * Synchronous helper for cases where you *know* the secret is already
   * loaded (e.g. early start‑up). It will block until the async fetch is
   * finished the first time.
   */
  getSync: (key) => {
    // Simple sync wrapper – **use only during boot**, not in request path.
    const promise = getSecret(key);
    // Node's top‑level await is available in recent versions, but we keep it
    // compatible with older LTS by using a tiny sync‑like hack:
    let result, error;
    promise.then(v => (result = v)).catch(e => (error = e));
    // Busy‑wait (fast) – in practice this runs only once at start‑up.
    const deasync = require('deasync');
    while (result === undefined && error === undefined) {
      deasync.runLoopOnce();
    }
    if (error) throw error;
    return result;
  },

  // Async version for when you can await.
  get: getSecret,
};
```

> **Why this helper?**  
> * Centralises the secret‑retrieval logic → you can switch providers by changing `SECRET_PROVIDER` and a few env mappings.  
> * Caches secrets in‑process, avoiding a network round‑trip on every request.  
> * Still works locally with a plain `.env` file, so developers don’t need a cloud account for everyday work.

