// app.js – Hardened version
require('dotenv').config();               // Load .env (never commit secrets)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

/* -------------------------------------------------------------
   1️⃣  Global Middleware – Security & Hardening
   ------------------------------------------------------------- */
// Remove the default X‑Powered‑By header (security misconfiguration)
app.disable('x-powered-by');

// Helmet adds a solid set of headers (Content‑Security‑Policy, HSTS, etc.)
app.use(
  helmet({
    // You can customise CSP later if you serve static assets.
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        // adjust as needed for scripts, styles, fonts, etc.
      },
    },
    referrerPolicy: { policy: 'no-referrer' },
  })
);

// CORS – whitelist only origins that need to call the API
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || []; // e.g. "https://app.example.com"
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow non‑browser (e.g., curl, Postman) when no origin is supplied
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      return callback(new Error('Not allowed by CORS'), false);
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// Rate limiting – 100 requests per IP per 15 minutes (tune to your traffic)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,   // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing (if you add POST/PUT later) with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Structured request logging (important for A09)
app.use(morgan('combined'));

/* -------------------------------------------------------------
   2️⃣  Simple health endpoint (public)
   ------------------------------------------------------------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/* -------------------------------------------------------------
   3️⃣  Users endpoint – now protected
   ------------------------------------------------------------- */
// Example: JWT‑based authentication middleware
const jwt = require('jsonwebtoken');

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) return res.sendStatus(401); // Unauthorized

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Forbidden (invalid/expired)
    req.user = user; // attach payload for role checks later
    next();
  });
}

/* Optional: role‑based access control (RBAC) */
function requireRole(role) {
  return (req, res, next) => {
    if (req.user?.role !== role) return res.sendStatus(403);
    next();
  };
}

/* Secure /users route */
app.get('/users', authenticateToken, requireRole('admin'), (req, res) => {
  // In a real app pull from a DB with param‑ized queries (prevents injection)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

/* -------------------------------------------------------------
   4️⃣  Global error handler – avoids leaking stack traces
   ------------------------------------------------------------- */
app.use((err, req, res, next) => {
  console.error(err);                // Log internally for ops
  if (process.env.NODE_ENV === 'production') {
    // Do not expose internal error details to the client
    return res.status(500).json({ error: 'Internal Server Error' });
  }
  // In non‑production, you may want more info
  res.status(500).json({ error: err.message, stack: err.stack });
});

/* -------------------------------------------------------------
   5️⃣  Server start – read port from env, enforce HTTPS in prod
   ------------------------------------------------------------- */
const PORT = process.env.PORT || 3000;

// If you terminate TLS at a reverse proxy (NGINX, ALB) you don't need to handle HTTPS here.
// Otherwise, you could use `https.createServer` with proper certificates.

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

