## 2️⃣ Recommended hardening steps (ordered by impact)

### 2.1 Add common security middleware (`helmet`, `cors`, `express-rate-limit`)

```bash
npm install helmet cors express-rate-limit morgan
```

```js
// app.js – AFTER the `express` import
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

// ------------------ Security middleware ------------------
app.use(helmet());                     // sets secure HTTP headers
app.use(cors({                         // restrict origins as needed
  origin: process.env.CORS_ORIGIN || '*', // change '*' to your front‑end domain in prod
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json());               // needed for body parsing (future POST/PUT)

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,   // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // apply only to routes that expose data

// Optional: request logging (helps with monitoring & forensic analysis)
app.use(morgan('combined'));
```

### 2.2 Remove the `X‑Powered‑By` header (info leakage)

```js
app.disable('x-powered-by'); // place before any route definitions
```

### 2.3 Centralise configuration (port, env, secrets)

```js
// At the top of the file
require('dotenv').config(); // npm i dotenv

const PORT = process.env.PORT || 3000;
```

Now start the server with `PORT=3000 node app.js` or via a `.env` file.

### 2.4 Add a **basic authentication** layer (or JWT, API‑key, etc.)

Below is a *simple* token‑based example.  Replace with your preferred auth strategy for production.

```js
// auth middleware – place before protected routes
function checkAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }

  // Expect "Bearer <token>"
  const token = authHeader.split(' ')[1];
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }
  next();
}

// Protect the /users route
app.get('/users', checkAuth, (req, res) => {
  // same implementation as before
});
```

Add `API_TOKEN=super‑secret-token` to your `.env` (or generate a JWT key pair).

### 2.5 Input validation (for future endpoints)

Even though the present routes have no parameters, any future endpoint that accepts request data **must** be validated.  A popular and lightweight choice is `express-validator`.

```bash
npm install express-validator
```

Example for a POST `/users` endpoint:

```js
const { body, validationResult } = require('express-validator');

app.post(
  '/users',
  checkAuth,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be 2‑50 characters long'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // safe to use req.body now
    const { name, email } = req.body;
    // … insert into DB with parameterised queries
    res.status(201).json({ id: 3, name, email });
  }
);
```

### 2.6 Central error handling (avoid information leakage)

```js
// place AFTER all route definitions
app.use((err, req, res, next) => {
  console.error(err);               // log the stack trace for ops
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});
```

### 2.7 Enforce TLS (HTTPS)

Node itself can serve TLS, but the easiest, most maintainable approach is to terminate TLS at a reverse‑proxy (NGINX, Traefik, Cloud‑flare, etc.) and keep the Express app **HTTP only** on an internal network.  If you must serve TLS directly:

```js
// server.js (separate entry point)
const https = require('https');
const fs = require('fs');
const app = require('./app');

const server = https.createServer(
  {
    key:  fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH)
  },
  app
);
server.listen(PORT, () => console.log(`HTTPS server listening on ${PORT}`));
```

### 2.8 Monitoring & health checks

- Keep `/health` as a *liveness* endpoint (already present).  
- Add a more detailed *readiness* probe that checks DB connections, external services, etc.
- Export metrics for Prometheus or similar (e.g., `prom-client`).

```bash
npm install prom-client
```

```js
const client = require('prom-client');
const collectDefaultMetrics = client.collectDefaultMetrics;
collectDefaultMetrics(); // registers CPU, memory, event‑loop metrics

app.get('/metrics', async (req, res) => {
  res.set('Content-Type', client.register.contentType);
  res.end(await client.register.metrics());
});
```

### 2.9 Keep dependencies up‑to‑date

```bash
npm audit
npm outdated
npm install express@latest   # repeat for other packages
```

Add a CI step (GitHub Actions, GitLab CI, etc.) that runs `npm audit --audit-level=high` on each PR.

