## 1️⃣ Centralise *how* secrets are obtained

Create a tiny **`config.js`** module that always reads from **environment variables first** and, if a variable is missing, falls back to a secrets‑manager fetch. All code (including `app.js`) will import the values from this module instead of reading `process.env` directly.

### 1.1 Install SDKs you need (example using AWS Secrets Manager)

```bash
npm install aws-sdk        # for AWS Secrets Manager
npm install @google-cloud/secret-manager   # for GCP Secret Manager (optional)
npm install @azure/keyvault-secrets @azure/identity  # for Azure (optional)
```

### 1.2 `config.js` (generic, supports multiple providers)

```js
// config.js
require('dotenv').config();                     // keep this for local dev only
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const { DefaultAzureCredential } = require('@azure/identity');
const { SecretClient } = require('@azure/keyvault-secrets');

const CACHE = new Map();                         // memo‑ise per‑process

/** Helper: fetch a secret from the chosen provider */
async function fetchSecretFromProvider(name) {
  // -----------------------------------------------------------------
  // 1️⃣ AWS Secrets Manager
  // -----------------------------------------------------------------
  if (process.env.AWS_SECRETS_MANAGER_ARN) {
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    const command = new GetSecretValueCommand({ SecretId: `${process.env.AWS_SECRETS_MANAGER_ARN}/${name}` });
    const { SecretString } = await client.send(command);
    return SecretString;
  }

  // -----------------------------------------------------------------
  // 2️⃣ GCP Secret Manager
  // -----------------------------------------------------------------
  if (process.env.GCP_PROJECT_ID) {
    const client = new SecretManagerServiceClient();
    const [version] = await client.accessSecretVersion({
      name: `projects/${process.env.GCP_PROJECT_ID}/secrets/${name}/versions/latest`,
    });
    return version.payload.data.toString('utf8');
  }

  // -----------------------------------------------------------------
  // 3️⃣ Azure Key Vault
  // -----------------------------------------------------------------
  if (process.env.AZURE_KEY_VAULT_URL) {
    const credential = new DefaultAzureCredential();
    const client = new SecretClient(process.env.AZURE_KEY_VAULT_URL, credential);
    const secret = await client.getSecret(name);
    return secret.value;
  }

  // -----------------------------------------------------------------
  // 4️⃣ No provider configured → throw
  // -----------------------------------------------------------------
  throw new Error(`No secret provider configured for "${name}"`);
}

/** Public API – request a secret */
async function getSecret(name, { required = true } = {}) {
  // 1️⃣ Return cached value if we already fetched it
  if (CACHE.has(name)) return CACHE.get(name);

  // 2️⃣ Prefer explicit environment variable (useful for CI / Docker env vars)
  if (process.env[name]) {
    CACHE.set(name, process.env[name]);
    return process.env[name];
  }

  // 3️⃣ Attempt provider fetch
  try {
    const secret = await fetchSecretFromProvider(name);
    CACHE.set(name, secret);
    return secret;
  } catch (err) {
    if (required) {
      console.error(`❗️ Unable to obtain required secret "${name}": ${err.message}`);
      process.exit(1);   // fail fast – you don't want the app to start with missing creds
    }
    return undefined;
  }
}

/* -----------------------------------------------------------------
   Export the values the rest of the app needs.
   Only expose the ones you actually use – this is a form of “least privilege”.
----------------------------------------------------------------- */
module.exports = {
  // DB
  databaseUrl: async () => await getSecret('DATABASE_URL'),

  // AWS – example for SDK usage
  awsCredentials: async () => ({
    accessKeyId: await getSecret('AWS_ACCESS_KEY_ID'),
    secretAccessKey: await getSecret('AWS_SECRET_ACCESS_KEY')
  }),

  // Third‑party APIs
  anthropicApiKey: async () => await getSecret('ANTHROPIC_API_KEY'),
  stripeSecretKey: async () => await getSecret('STRIPE_SECRET_KEY'),
  logfireToken: async () => await getSecret('LOGFIRE_TOKEN')
};
```

**Why this solves the original problem**

| Issue | How `config.js` addresses it |
|-------|-----------------------------|
| **Plain‑text file in repo** | Secrets are never read from a file in production – the code only reads them from environment variables *or* from a cloud‑managed secret store. |
| **Accidental logging of `process.env`** | All secrets are retrieved through a **private async getter**; you never expose the whole `process.env` object. |
| **No rotation/audit** | Cloud secret managers keep a versioned history and allow rotation without redeploying code. |
| **Development convenience** | `require('dotenv').config()` still works locally – you can create a private `.env.local` (git‑ignored) that mirrors the shape of the real secrets. |

