## 2️⃣ Adjust the application to use the new `config.js`

Below is a **minimal example** for the `/users` route that now lazily fetches the database URL *once* and uses it to initialise a DB client. You can follow the same pattern for any other secret.

```js
// app.js (or server.js – any file that needs a secret)
const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const config = require('./config');   // <-- new module

const app = express();

app.disable('x-powered-by');
app.use(helmet());
app.use(cors({ origin: process.env.CORS_ORIGIN || '*'}));
app.use(express.json());
app.use(morgan('combined'));

const apiLimiter = rateLimit({ windowMs: 15*60*1000, max: 100 });
app.use('/users', apiLimiter);

/* -------------------------------------------------
   Example: initialise a DB client *once* using the secret.
   In a real project you would probably use a pool (pg, knex, prisma…)
------------------------------------------------- */
let db;   // will hold a lazily‑created client
async function getDb() {
  if (db) return db;
  const connectionString = await config.databaseUrl();   // fetch secret
  const { Client } = require('pg');
  db = new Client({ connectionString });
  await db.connect();
  return db;
}

/* -------------------------------------------------
   Protected /users route (still uses token auth from before)
------------------------------------------------- */
function checkAuth(req, res, next) {
  const auth = req.headers.authorization?.split(' ')[1];
  if (!auth || auth !== process.env.API_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

app.get('/users', checkAuth, async (req, res, next) => {
  try {
    const client = await getDb();
    const { rows } = await client.query('SELECT id, name, email FROM users LIMIT 100');
    res.json(rows);
  } catch (e) {
    next(e);
  }
});

/* -------------------------------------------------
   Health & error handling (unchanged)
------------------------------------------------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.use((err, req, res, next) => {
  console.error(err);
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

module.exports = app;
```

### How this works in practice

| Environment | What you **must** set |
|-------------|-----------------------|
| **Local dev** | Create a **`.env.local`** (git‑ignored) with the same variable names (`DATABASE_URL`, `AWS_ACCESS_KEY_ID`, …). `dotenv` will load it. |
| **Docker / Kubernetes** | Pass the secrets as **environment variables** (via `docker run -e` or a K8s `Secret` mounted as env). No `.env` file needed. |
| **AWS** | Store each secret in **AWS Secrets Manager** and give the task role permission `secretsmanager:GetSecretValue`. Set `AWS_SECRETS_MANAGER_ARN=arn:aws:secretsmanager:region:account-id:secret:my‑app` and optionally `AWS_REGION`. |
| **GCP** | Store each secret in **Secret Manager**, set `GCP_PROJECT_ID=<project-id>`. The service account attached to the pod must have `secretmanager.secretAccessor`. |
| **Azure** | Store each secret in **Key Vault**, set `AZURE_KEY_VAULT_URL=https://my‑kv.vault.azure.net/`. The managed identity must have `get` permission on the keys. |

